$source = 'service/business-website-design.html'
$copy = 'service/business-website-design-in-nigeria.html'
$root = Get-Location
$c = [IO.File]::ReadAllText((Join-Path $root $source), [Text.UTF8Encoding]::new($false))

$newSection = @'
    <section class="bw-paper bw-section bw-role"><div class="bw-shell"><div class="bw-role-grid"><div class="bw-role-visual"><div class="bw-role-art"><img src="/assets/images/optimized-live/nexus-1000.jpg" alt="Nexus Construction website project designed by Drey Studio" width="1000" height="1000" loading="lazy"><div class="bw-role-badge"><span>Selected project</span><strong>Nexus Construction</strong><small>Business website / Drey Studio</small></div></div><p class="bw-role-caption">A project visual from Drey Studio's selected work.</p></div><div class="bw-role-copy"><p class="bw-kicker dark">The role of the website</p><h2 class="bw-h2 dark">A business website should make the next step clear.</h2><p>Before a customer calls, visits or sends a message, they are deciding whether the business looks relevant, reliable and worth their time. The website should make that decision easier.</p><p>Drey Studio creates business websites around the information people need to understand your offer: what you do, who you help, what you have done and how someone can take the next step.</p><div class="bw-role-points"><article><span class="bw-role-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 12h14M13 6l6 6-6 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span><div><h3>Clear routes to enquiry</h3><p>Service pages, contact routes and calls to action are placed where visitors are ready to move.</p></div></article><article><span class="bw-role-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M4 5h16v14H4zM8 9h8M8 13h5" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span><div><h3>Designed around your offer</h3><p>Goals, audience, content and user journeys shape the interface before the visual details are polished.</p></div></article></div><div class="bw-role-meters"><div class="bw-role-meter"><div><strong>Clear service structure</strong><span>Core foundation</span></div><i aria-hidden="true"><b></b></i></div><div class="bw-role-meter"><div><strong>Responsive experience</strong><span>Core foundation</span></div><i aria-hidden="true"><b></b></i></div></div><div class="bw-actions"><a class="bw-btn outline-dark" href="/website-developer-nigeria">See how Drey works in Nigeria</a></div></div></div></div></section>
'@
$pattern = '(?s)    <section class="bw-paper bw-section"><div class="bw-shell">.*?</section>'
$c = [regex]::Replace($c, $pattern, $newSection, 1)

$css = @'
    .bw-role-grid{display:grid;grid-template-columns:minmax(300px,.86fr) minmax(0,1.14fr);gap:88px;align-items:center}.bw-role-visual{min-width:0}.bw-role-art{position:relative;padding:0 34px 34px 0}.bw-role-art:before{content:"";position:absolute;right:0;bottom:0;width:82%;height:82%;background:var(--bw-paper2);border:1px solid var(--bw-paperline)}.bw-role-art img{position:relative;z-index:1;width:100%;aspect-ratio:1/1;object-fit:cover;border:10px solid var(--bw-dark);box-shadow:0 24px 55px rgba(32,26,37,.18)}.bw-role-badge{position:absolute;z-index:2;right:-8px;bottom:10px;width:min(245px,64%);padding:19px 20px;background:var(--bw-dark);color:#fff;box-shadow:0 18px 35px rgba(32,26,37,.22)}.bw-role-badge span,.bw-role-badge small{display:block;color:var(--bw-lav);font:700 10px/1.2 Inter,sans-serif;letter-spacing:.12em;text-transform:uppercase}.bw-role-badge strong{display:block;margin:8px 0 5px;font:700 20px/1.15 Inter,sans-serif}.bw-role-caption{margin:16px 0 0;color:var(--bw-copy);font-size:13px}.bw-role-copy>p:not(.bw-kicker){max-width:650px;margin:22px 0 0;font-size:17px;line-height:1.78}.bw-role-copy .bw-h2{max-width:650px}.bw-role-points{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:36px}.bw-role-points article{display:grid;grid-template-columns:26px 1fr;gap:12px}.bw-role-icon{color:#7355a7}.bw-role-icon svg{width:22px;height:22px}.bw-role-points h3{margin:0;color:var(--bw-dark);font:700 16px/1.3 Inter,sans-serif}.bw-role-points p{margin:7px 0 0;font-size:14px;line-height:1.6}.bw-role-meters{display:grid;gap:18px;margin-top:36px}.bw-role-meter>div{display:flex;justify-content:space-between;gap:18px;margin-bottom:9px}.bw-role-meter strong{color:var(--bw-dark);font:700 14px/1.3 Inter,sans-serif}.bw-role-meter span{color:var(--bw-copy);font-size:12px}.bw-role-meter i{display:block;height:10px;border-radius:99px;background:#e1dce7;overflow:hidden}.bw-role-meter b{display:block;width:100%;height:100%;border-radius:inherit;background:#7355a7}.bw-role-copy>.bw-actions{margin-top:32px}
    @media(max-width:900px){.bw-role-grid{grid-template-columns:1fr;gap:56px}.bw-role-copy{max-width:720px}.bw-role-points{grid-template-columns:1fr 1fr}}
    @media(max-width:620px){.bw-role-art{padding:0 18px 22px 0}.bw-role-badge{right:-2px;bottom:0;width:62%;padding:15px}.bw-role-badge strong{font-size:17px}.bw-role-points{grid-template-columns:1fr;gap:24px}.bw-role-meter>div{display:block}.bw-role-meter span{display:block;margin-top:4px}}
'@
if ($c -notmatch 'bw-role-grid') { $c = $c.Replace('  </style>', $css + '  </style>') }
[IO.File]::WriteAllText((Join-Path $root $source), $c, [Text.UTF8Encoding]::new($false))
Copy-Item (Join-Path $root $source) (Join-Path $root $copy) -Force
Write-Output 'Rebuilt and synchronized the website-role section.'
